#include "ZekumoClient.h"
#include "HttpModule.h"
#include "Interfaces/IHttpResponse.h"
#include "Serialization/JsonSerializer.h"
#include "Serialization/JsonWriter.h"
#include "WebSocketsModule.h"

FZekumoClient::FZekumoClient(FString A,FString B,FString T):AppId(MoveTemp(A)),BaseUrl(MoveTemp(B)),Token(MoveTemp(T)){BaseUrl.RemoveFromEnd(TEXT("/"));}
FString FZekumoClient::Segment(const FString& V){return FGenericPlatformHttp::UrlEncode(V);}
void FZekumoClient::Request(const FString&M,const FString&P,const TSharedPtr<FJsonObject>&B,FZekumoResponse D,bool Auth){auto R=FHttpModule::Get().CreateRequest();R->SetURL(BaseUrl+P);R->SetVerb(M);R->SetHeader(TEXT("Accept"),TEXT("application/json"));if(Auth&&!Token.IsEmpty())R->SetHeader(TEXT("Authorization"),TEXT("Bearer ")+Token);if(B){FString S;auto W=TJsonWriterFactory<>::Create(&S);FJsonSerializer::Serialize(B.ToSharedRef(),W);R->SetHeader(TEXT("Content-Type"),TEXT("application/json"));R->SetContentAsString(S);}R->OnProcessRequestComplete().BindLambda([D](FHttpRequestPtr, FHttpResponsePtr X,bool Ok){FZekumoError E;TSharedPtr<FJsonObject> O;if(X){E.Status=X->GetResponseCode();auto Rd=TJsonReaderFactory<>::Create(X->GetContentAsString());FJsonSerializer::Deserialize(Rd,O);}if(!Ok||!X||E.Status>=300){auto V=O?O->GetObjectField(TEXT("error")):nullptr;E.Code=V?V->GetStringField(TEXT("code")):FString::Printf(TEXT("http_%d"),E.Status);E.Message=V?V->GetStringField(TEXT("message")):(X?X->GetContentAsString():TEXT("transport error"));}D.ExecuteIfBound(O,E);});R->ProcessRequest();}
void FZekumoClient::Login(const FString&P,const TSharedPtr<FJsonObject>&B,FZekumoResponse D){B->SetStringField(TEXT("app_id"),AppId);Request(TEXT("POST"),P,B,FZekumoResponse::CreateLambda([this,D](const TSharedPtr<FJsonObject>&O,const FZekumoError&E){if(O&&E.Status<300)Token=O->GetStringField(TEXT("token"));D.ExecuteIfBound(O,E);}),false);}
void FZekumoClient::LoginGuest(const FString&I,const FString&N,FZekumoResponse D){auto B=MakeShared<FJsonObject>();B->SetStringField(TEXT("provider"),TEXT("guest"));B->SetStringField(TEXT("device_id"),I);B->SetStringField(TEXT("nickname"),N);Login(TEXT("/v1/auth/login"),B,D);}void FZekumoClient::LoginPassword(const FString&U,const FString&P,FZekumoResponse D){auto B=MakeShared<FJsonObject>();B->SetStringField(TEXT("provider"),TEXT("password"));B->SetStringField(TEXT("username"),U);B->SetStringField(TEXT("password"),P);Login(TEXT("/v1/auth/login"),B,D);}void FZekumoClient::LoginTicket(const FString&T,FZekumoResponse D){auto B=MakeShared<FJsonObject>();B->SetStringField(TEXT("provider"),TEXT("sso"));B->SetStringField(TEXT("ticket"),T);Login(TEXT("/v1/auth/login"),B,D);}void FZekumoClient::Register(const FString&U,const FString&P,const FString&N,FZekumoResponse D){auto B=MakeShared<FJsonObject>();B->SetStringField(TEXT("provider"),TEXT("password"));B->SetStringField(TEXT("username"),U);B->SetStringField(TEXT("password"),P);B->SetStringField(TEXT("nickname"),N);Login(TEXT("/v1/auth/register"),B,D);}
void FZekumoClient::ConnectRealtime(){FString U=BaseUrl;U.ReplaceInline(TEXT("https://"),TEXT("wss://"));U.ReplaceInline(TEXT("http://"),TEXT("ws://"));Socket=FWebSocketsModule::Get().CreateWebSocket(U+TEXT("/v1/ws?token=")+Segment(Token));Socket->OnMessage().AddLambda([this](const FString&M){TSharedPtr<FJsonObject>O;auto R=TJsonReaderFactory<>::Create(M);if(FJsonSerializer::Deserialize(R,O)&&O)OnRealtimeEvent.Broadcast(O->GetStringField(TEXT("type")),O->TryGetField(TEXT("data")));});Socket->Connect();}
void FZekumoClient::SendRealtime(const FString&T,const TSharedPtr<FJsonValue>&D){if(!Socket||!Socket->IsConnected())return;auto O=MakeShared<FJsonObject>();O->SetStringField(TEXT("type"),T);if(D)O->SetField(TEXT("data"),D);FString S;auto W=TJsonWriterFactory<>::Create(&S);FJsonSerializer::Serialize(O.ToSharedRef(),W);Socket->Send(S);}void FZekumoClient::CloseRealtime(){if(Socket)Socket->Close();Socket.Reset();}
